```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An OWL ontology modelling securities, debt, equity, hybrid and derivative financial instruments, investment funds, issuers, investors and markets, built strictly from the supplied corpus." .

#################################################################
# TOP LEVEL: FinancialInstrument, Asset
#################################################################

fis:Asset a owl:Class ;
    rdfs:label "asset" ;
    rdfs:comment "Anything that can serve as the underlier of a derivative contract: a commodity, a financial instrument, a price index, a currency, or an interest rate." .

fis:FinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled. Financial instruments divide into cash instruments and derivative instruments." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "An instrument whose value is determined directly by the markets: securities (readily transferable) or loans/deposits (requiring mutual agreement to transfer)." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "derivative" , "derivative instrument" ;
    rdfs:comment "A contract between a buyer and seller that derives its value from an underlying asset, index, rate, or event. Every derivative has an underlier, a future act, a price, and a future date. NOTE/CONFLICT: most of the corpus (the general financial-instrument classification, the wikibook) treats derivatives as a category distinct from 'securities' (cash instruments). However, the US securities-law passage explicitly lists derivatives as one of three categories of 'security' alongside debt and equity securities. This ontology follows the majority/general classification, keeping Derivative disjoint from CashInstrument/Security." ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasDeliveryDate ; owl:someValuesFrom xsd:date ] ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasAgreedPrice ; owl:someValuesFrom xsd:decimal ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A cash instrument such as a loan or deposit, where both borrower and lender must agree on a transfer (not readily transferable like a security)." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan ;
    rdfs:comment "A loan secured by real estate, used as collateral underlying mortgage-backed securities." .

fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ;
    rdfs:comment "A mortgage secured by single-family, one- to four-unit residential real estate." .

fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ;
    rdfs:comment "A mortgage secured by commercial and multi-family properties such as offices, hotels, and retail." .

[ a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A cash instrument representing funds deposited with a bank, characteristic of money market instruments like certificates of deposit." .

#################################################################
# Security and its three/four broad branches
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" ;
    rdfs:comment "A tradable financial asset. Legal definitions vary by jurisdiction; some jurisdictions restrict 'security' to equity and fixed income instruments only, others include instruments such as equity warrants." .

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "debt security" ;
    rdfs:comment "Securities such as debentures, bonds, deposits, notes or commercial paper. The holder is entitled to payment of principal and interest." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "equity security" ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership. Holders have a residual claim after creditors are paid." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "hybrid security" ;
    rdfs:comment "Securities that combine characteristics of both debt and equity securities, e.g. preference shares, convertible bonds, and equity warrants. Not disjoint from DebtSecurity/EquitySecurity because instruments such as preferred stock and convertible bonds are explicitly stated to be both." .

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:label "investment fund" ;
    rdfs:comment "An investment vehicle (mutual fund, ETF, hedge fund) that pools money from many investors to purchase securities." .

owl:disjointWith_DebtEquity a rdf:Description . 
fis:DebtSecurity owl:disjointWith fis:EquitySecurity .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
    rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:Investor ;
    rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:Derivative ; rdfs:range fis:Asset ;
    rdfs:label "has underlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset ;
    rdfs:label "has collateral" .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:Option .

fis:hasConversionTarget a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:CommonStock ;
    rdfs:comment "Relates a convertible security to the class of common stock into which it may be converted." .

fis:hasExchangeTarget a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:CommonStock ;
    rdfs:comment "Relates an exchangeable bond to shares of a corporation other than its own issuer." .

fis:hasReferenceEntity a owl:ObjectProperty ;
    rdfs:domain fis:Swap ; rdfs:range fis:Issuer .

fis:hasPortfolioHolding a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range fis:Security .

fis:hasDividendPayment a owl:ObjectProperty ;
    rdfs:domain fis:Stock ; rdfs:range fis:Dividend .

fis:hasCouponPayment a owl:ObjectProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:CouponPayment .

fis:hasPriorityOver a owl:ObjectProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:Security ;
    rdfs:comment "Indicates seniority of claim on dividends/assets, e.g. preferred stock has priority over common stock." .

fis:isTradedOn a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Market .

fis:hasIssuanceMethod a owl:ObjectProperty ;
    rdfs:domain fis:Security ; rdfs:range fis:IssuanceMethod .

fis:hasRepaymentSource a owl:ObjectProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:RepaymentSource .

fis:hasBenchmarkIndex a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ; rdfs:range fis:PriceIndex .

fis:hasReferenceRate a owl:ObjectProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:InterestRateIndex .

fis:hasPrincipalIndexation a owl:ObjectProperty ;
    rdfs:domain fis:Bond ; rdfs:range fis:PriceIndex .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
    rdfs:label "has face value" , "has par value" , "has principal" , "has nominal amount" .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasYield a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasDeliveryDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ; rdfs:range xsd:date .

fis:hasAgreedPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ; rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Swap ; rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasMarketPrice a owl:DatatypeProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:decimal .

fis:hasVotingRights a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Stock ; rdfs:range xsd:boolean .

fis:hasStandardizedTerms a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .

fis:hasOptionType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:string .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:string .

fis:hasTermLength a owl:DatatypeProperty ;
    rdfs:domain fis:MoneyMarketInstrument ; rdfs:range xsd:integer .

fis:hasAmount a owl:DatatypeProperty ;
    rdfs:domain fis:Payment ; rdfs:range xsd:decimal .

fis:hasPremium a owl:DatatypeProperty ;
    rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:isSecuredByCollateral a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean .

fis:isSeniorDebt a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean .

fis:retainsCollateralOnBalanceSheet a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:isCertificated a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasBearerForm a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:CertificatedSecurity ; rdfs:range xsd:boolean .

fis:isDivided a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:hasFungibility a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ; rdfs:range xsd:boolean .

#################################################################
# Underlying asset classes
#################################################################

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRateIndex a owl:Class ; rdfs:subClassOf fis:Asset .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Asset .

#################################################################
# Certificate-form / divisibility / fungibility cross-cutting classes
#################################################################

fis:CertificatedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isCertificated ; owl:hasValue true ] ) ] .

fis:NonCertificatedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isCertificated ; owl:hasValue false ] ) ] ;
    rdfs:comment "Non-certificated, electronic 'book entry only' securities." .

[ a owl:AllDisjointClasses ; owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) ] .

fis:BearerSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:CertificatedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasBearerForm ; owl:hasValue true ] ) ] ;
    rdfs:comment "Entitles the holder to rights merely by holding the security; transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:CertificatedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasBearerForm ; owl:hasValue false ] ) ] ;
    rdfs:comment "Entitles the holder to rights only if they appear on a security register." .

[ a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:DividedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isDivided ; owl:hasValue true ] ) ] ;
    rdfs:comment "Each instrument constitutes a separate asset/covenant, legally distinct from other securities in the same issue." .

fis:UndividedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isDivided ; owl:hasValue false ] ) ] ;
    rdfs:comment "The entire issue is one asset, each security being a fractional part of the undivided whole." .

[ a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue true ] ) ] ;
    rdfs:comment "All holdings of the security are treated identically and are interchangeable." .

fis:NonFungibleSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue false ] ) ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) ] .

#################################################################
# DEBT SECURITY family
#################################################################

fis:SecuredDebtSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:isSecuredByCollateral ; owl:hasValue true ] ) ] .

fis:UnsecuredDebtSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:isSecuredByCollateral ; owl:hasValue false ] ) ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:SecuredDebtSecurity fis:UnsecuredDebtSecurity ) ] .

fis:SeniorDebtSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:isSeniorDebt ; owl:hasValue true ] ) ] ;
    rdfs:comment "Holders have priority in a bankruptcy of the issuer." .

fis:SubordinatedDebtSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:isSeniorDebt ; owl:hasValue false ] ) ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:SeniorDebtSecurity fis:SubordinatedDebtSecurity ) ] .

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Under a bond, the issuer owes the holder a debt and is obliged to repay principal plus interest (coupon) over a specified time; generally the most common form of longer-term debt security." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less; CDs and commercial paper are money market instruments, not bonds." .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

fis:Debenture a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:UnsecuredDebtSecurity ) ] ;
    rdfs:comment "Unsecured bonds are called debentures; debentures typically have a long maturity (at least ten years)." .

#################################################################
# Bond issuer-based subtypes
#################################################################

fis:GovernmentBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:label "sovereign bond" , "treasury bond" , "gilt" .

fis:MunicipalBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
    rdfs:label "muni" .

fis:SupranationalBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "A bond issued by a government to fund military operations during wartime." .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "US government bond with maturity of two to ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "US government bond with the longest maturity, 20-30 years." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "Inflation-indexed US government bond (TIPS) whose principal adjusts with the Consumer Price Index." .

#################################################################
# Municipal bond subtypes via RepaymentSource
#################################################################

fis:RepaymentSource a owl:Class ;
    rdfs:comment "The source from which a municipal bond is repaid." .
fis:GeneralTaxingPower a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
fis:DedicatedRevenueStream a owl:Class ; rdfs:subClassOf fis:RepaymentSource .
fis:PropertyTaxAssessment a owl:Class ; rdfs:subClassOf fis:GeneralTaxingPower .

[ a owl:AllDisjointClasses ; owl:members ( fis:GeneralTaxingPower fis:DedicatedRevenueStream ) ] .

fis:GeneralObligationBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:GeneralTaxingPower ] ) ] ;
    rdfs:comment "Principal and interest secured by the full faith and credit/taxing power of the issuer; usually the most secure municipal bond." .

fis:RevenueBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MunicipalBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:DedicatedRevenueStream ] ) ] ;
    rdfs:comment "Repayment from a specified stream of future income; typically non-recourse." .

[ a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:AssessmentBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:GeneralObligationBond
        [ a owl:Restriction ; owl:onProperty fis:hasRepaymentSource ; owl:someValuesFrom fis:PropertyTaxAssessment ] ) ] ;
    rdfs:comment "Promises repayment based on property tax assessments; generally considered a form of general obligation bond." .

#################################################################
# Credit-quality bond subtypes
#################################################################

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
    rdfs:comment "Bonds rated AAA, AA, A or BBB; also called high grade." .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ;
    rdfs:label "junk bond" ;
    rdfs:comment "Bonds rated BB and below, i.e. below investment grade." .

[ a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Bond issued to raise finance for climate change mitigation or adaptation projects." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Agreement for public sector entities to repay private investors after verified social outcomes are met." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Issuer redeems randomly selected bonds within the issue, sometimes above face value." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond that matures in installments over a period of time." .
fis:MethuselahBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond with a maturity of 50 years or longer." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A security issued internationally outside its domestic market, denominated in a currency different from the issuer's domicile; characteristically underwritten, unsecured, interest paid gross." .

#################################################################
# Collateral/balance-sheet based bond subtypes
#################################################################

fis:AssetBackedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
        [ a owl:Restriction ; owl:onProperty fis:retainsCollateralOnBalanceSheet ; owl:hasValue false ] ) ] ;
    rdfs:subClassOf fis:SecuredDebtSecurity ;
    rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from a pool of assets sold off the issuer's balance sheet (e.g. via a special purpose vehicle)." .

fis:CoveredBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
        [ a owl:Restriction ; owl:onProperty fis:retainsCollateralOnBalanceSheet ; owl:hasValue true ] ) ] ;
    rdfs:subClassOf fis:SecuredDebtSecurity ;
    rdfs:comment "Backed by cash flows from mortgages or public sector assets which, unlike asset-backed securities, remain on the issuer's balance sheet." .

fis:MortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

[ a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "pay-through bond" ;
    rdfs:comment "A debt obligation collateralized by the mortgage assets it owns, divided into tranches with different maturities and payment priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Each mortgage payment is split into interest and principal components which are separated into distinct securities." .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "A bond with cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "A bond with cash flows backed by the principal repayment component of mortgage payments." .

[ a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
    rdfs:comment "A structured asset-backed security backed by debt obligations, often other asset-backed securities, sliced into tranches." .

#################################################################
# Embedded-option bond subtypes
#################################################################

fis:CallableBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
    rdfs:comment "Gives the issuer the right to repay the bond before the maturity date on call dates." .

fis:PutableBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
    rdfs:label "retractable bond" ;
    rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity on put dates." .

fis:BulletBond a owl:Class ;
    owl:equivalentClass [ owl:intersectionOf ( fis:Bond
